# Try shifting all 5s by one pixel in various directions
arr = np.array(input_grid)

def apply_shift(direction):
    """Shift the grid in a given direction"""
    if direction == 'right':
        return np.roll(arr, 1, axis=1)
    elif direction == 'left':
        return np.roll(arr, -1, axis=1)
    elif direction == 'up':
        return np.roll(arr, 1, axis=0)
    elif direction == 'down':
        return np.roll(arr, -1, axis=0)

for direction in ['right', 'left', 'up', 'down']:
    shifted = apply_shift(direction)
    print(f"\n{direction} shift, row 0:", ' '.join(map(str, shifted[0])))

# Build and print the full grid
arr = np.array(input_grid)
n_rows, n_cols = arr.shape

result_conditional_swap = []
for i in range(n_rows):
    has_adjacent_duplicate = False
    if i > 0 and np.array_equal(arr[i], arr[i-1]):
        has_adjacent_duplicate = True
    if i < n_rows - 1 and np.array_equal(arr[i], arr[i+1]):
        has_adjacent_duplicate = True

    if has_adjacent_duplicate:
        result_conditional_swap.append(arr[i].tolist())
    else:
        new_row = [5 if v == 1 else 1 for v in arr[i]]
        result_conditional_swap.append(new_row)

output = [[int(x) for x in row] for row in result_conditional_swap]

# Print first few rows as verification
print("First 3 rows:")
for i in range(3):
    print(f"Row {i}: {' '.join(map(str, output[i]))}")

print("\nLast 2 rows:")
